<?php
namespace Modules\Ran\Http\Controllers;
use Modules\Ran\Entities\{Stocktake,StockLot};use Modules\Ran\Http\Requests\StocktakeRequest;use Modules\Ran\Services\StocktakeService;
class StocktakeController extends RanController {public function index(){return view('ran::stocktakes.index',array_merge($this->pageOptions(),['stocktakes'=>Stocktake::latest('stocktake_date')->latest('id')->paginate(25)]));} public function create(){return view('ran::stocktakes.form',array_merge($this->pageOptions(),['lots'=>StockLot::with('item')->where('stock_status','available')->orderBy('lot_no')->get()]));} public function store(StocktakeRequest $request,StocktakeService $service){$stocktake=$service->create($request->validated());return $this->success('Stocktake saved.','ran.stocktakes.show',[$stocktake]);} public function show(Stocktake $stocktake){return view('ran::stocktakes.show',array_merge($this->pageOptions(),['stocktake'=>$stocktake->load('lines.stockLot.item')]));} public function post(Stocktake $stocktake,StocktakeService $service){$service->post($stocktake);return back()->with('status','Stocktake variances posted.');}}
